//! 🗃️ Borrowed final rows prepare derived cache owners before one-header commits.
use semio_s_artifact_layout_layout_model::{Page,ParentPage,Layer};
use semio_framework_os_kernel::ApplyCapability;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,sort::{HeapSortCursor,HeapSortWork},retained_clone::{RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use std::{cmp::Ordering,mem::{size_of,ManuallyDrop}};
/// 👁 Stable registration lends final row IDs without materializing Page or Frame payloads.
pub trait PageLayerCacheSource{fn identity(&self)->usize;fn layer_count(&self)->usize;fn layer_id(&self,index:usize)->&str;fn frame_count(&self)->usize;fn frame_id(&self,index:usize)->&str;fn frame_layer_id(&self,index:usize)->&str;}
#[derive(semio_framework_value::RetireOwned)]
struct Owners{sorted:Vec<usize>,counts:Vec<usize>,objects:Vec<Vec<String>>,layer_ids:Vec<String>,text:String}
#[derive(Clone,Copy)]
struct Control{phase:u8,identity:usize,layers:usize,frames:usize,index:usize,frame:usize,low:usize,high:usize,scan:usize,search:u8,offset:usize,copy_stage:u8,pointer:usize,length:usize,copy_offset:usize,install:usize,sort:HeapSortCursor}
/// 🧳 Every prepared and displaced cache stays under original funded retirement custody.
pub struct PageCachePreparation{owners:ManuallyDrop<Option<Owners>>,control:Control,retirement:RetainedCloneClose,closing:bool}
impl Default for PageCachePreparation{fn default()->Self{Self::new()}}
impl PageCachePreparation{
 pub fn new()->Self{Self{owners:ManuallyDrop::new(Some(Owners{sorted:Vec::new(),counts:Vec::new(),objects:Vec::new(),layer_ids:Vec::new(),text:String::new()})),control:Control{phase:0,identity:0,layers:0,frames:0,index:0,frame:0,low:0,high:0,scan:0,search:0,offset:0,copy_stage:0,pointer:0,length:0,copy_offset:0,install:0,sort:HeapSortCursor::new(0)},retirement:Default::default(),closing:false}}
 fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
 fn owners(&self)->&Owners{self.owners.as_ref().expect("retained original cache owners")}
 fn check(&self,s:&impl PageLayerCacheSource)->Result<(),ValueError>{let c=self.control;if c.phase!=0&&(s.identity()!=c.identity||s.layer_count()!=c.layers||s.frame_count()!=c.frames){return Err(Self::fault("page cache source identity changed"))}Ok(())}
 fn extent(count:usize,element:usize)->Result<usize,ValueError>{count.checked_mul(element).ok_or_else(||Self::fault("page cache source extent overflow"))}
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Control>()+4*size_of::<Vec<String>>()+4*size_of::<usize>(),depth:1,..Default::default()}}
 fn text<'a>(c:Control,s:&'a impl PageLayerCacheSource)->&'a str{if c.phase==7{s.layer_id(c.index)}else{s.frame_id(c.frame)}}
 fn text_active(c:Control)->bool{(c.phase==7&&c.index<c.layers)||(c.phase==10&&c.search==3)}
 pub fn demand(&self,s:&impl PageLayerCacheSource)->Result<RetirementDemand,ValueError>{self.check(s)?;let c=self.control;if self.closing||c.phase>11{return Err(Self::fault("page cache preparation is settled"))}let mut d=Self::fixed();d.capacity_bytes=match c.phase{1=>Self::extent(c.layers,size_of::<usize>())?,2=>Self::extent(c.layers,size_of::<usize>())?,3=>Self::extent(c.layers,size_of::<Vec<String>>())?,4=>Self::extent(c.layers,size_of::<String>())?,9 if c.index<c.layers=>Self::extent(self.owners().counts[c.index],size_of::<String>())?,_=>0};if Self::text_active(c){let text=Self::text(c,s);if c.copy_stage>0&&(text.as_ptr()as usize!=c.pointer||text.len()!=c.length){return Err(Self::fault("page cache borrowed text source changed"))}if c.copy_stage==0{d.capacity_bytes=text.len()}else if c.copy_stage==1{let mut end=(c.copy_offset+256).min(c.length);while !text.is_char_boundary(end){end-=1}d.copy_bytes+=end-c.copy_offset;}}Ok(d)}
 fn compare(c:&mut Control,a:&str,b:&str)->Option<Ordering>{let end=(c.offset+256).min(a.len()).min(b.len());for i in c.offset..end{let order=a.as_bytes()[i].cmp(&b.as_bytes()[i]);if order!=Ordering::Equal{c.offset=0;return Some(order)}}c.offset=end;if end==a.len()||end==b.len(){c.offset=0;Some(a.len().cmp(&b.len()))}else{None}}
 fn copy_text(c:&mut Control,o:&mut Owners,text:&str)->Result<usize,ValueError>{match c.copy_stage{0=>{c.pointer=text.as_ptr()as usize;c.length=text.len();c.copy_offset=0;o.text.try_reserve_exact(text.len()).map_err(|_|Self::fault("page cache text reservation failed"))?;c.copy_stage=1;Ok(o.text.capacity())},1=>{let mut end=(c.copy_offset+256).min(c.length);while !text.is_char_boundary(end){end-=1}o.text.push_str(&text[c.copy_offset..end]);c.copy_offset=end;if end==c.length{c.copy_stage=2}Ok(0)},2=>{let text=std::mem::take(&mut o.text);if c.phase==7{o.layer_ids.push(text);c.index+=1}else{o.objects[o.sorted[c.scan]].push(text);c.scan+=1;c.search=2;}c.copy_stage=0;c.pointer=0;c.length=0;c.copy_offset=0;Ok(0)},_=>unreachable!()}}
 pub fn advance(&mut self,s:&impl PageLayerCacheSource,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(s)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut c=self.control;let o=self.owners.as_mut().expect("original cache owner");let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if Self::text_active(c){p.retained_capacity_bytes=Self::copy_text(&mut c,o,Self::text(self.control,s)).map_err(|e|e.with_retained_progress(p))?;}else{match c.phase{
 0=>{c.identity=s.identity();c.layers=s.layer_count();c.frames=s.frame_count();Self::extent(c.layers,size_of::<Vec<String>>())?;c.phase=1;},
 1=>{o.sorted.try_reserve_exact(c.layers).map_err(|_|Self::fault("page cache sorted reservation failed"))?;p.retained_capacity_bytes=o.sorted.capacity()*size_of::<usize>();c.phase=2;},
 2=>{o.counts.try_reserve_exact(c.layers).map_err(|_|Self::fault("page cache counts reservation failed"))?;p.retained_capacity_bytes=o.counts.capacity()*size_of::<usize>();c.phase=3;},
 3=>{o.objects.try_reserve_exact(c.layers).map_err(|_|Self::fault("page cache object headers reservation failed"))?;p.retained_capacity_bytes=o.objects.capacity()*size_of::<Vec<String>>();c.phase=4;},
 4=>{o.layer_ids.try_reserve_exact(c.layers).map_err(|_|Self::fault("page cache layer headers reservation failed"))?;p.retained_capacity_bytes=o.layer_ids.capacity()*size_of::<String>();c.phase=5;},
 5=>{if c.index<c.layers{o.sorted.push(c.index);o.counts.push(0);o.objects.push(Vec::new());c.index+=1;}else{c.sort=HeapSortCursor::new(c.layers);c.index=0;c.phase=6;}},
 6=>{match c.sort.next(){HeapSortWork::Complete=>c.phase=7,HeapSortWork::Compare{left,right}=>{if let Some(order)=Self::compare(&mut c,s.layer_id(o.sorted[left]),s.layer_id(o.sorted[right])){c.sort.advance(Some(order)).map_err(|_|Self::fault("page cache sort observation invalid"))?;}},HeapSortWork::Swap{left,right}=>{o.sorted.swap(left,right);c.sort.advance(None).map_err(|_|Self::fault("page cache sort swap invalid"))?;},HeapSortWork::Advance=>c.sort.advance(None).map_err(|_|Self::fault("page cache sort advance invalid"))?}},
 7=>{c.phase=8;c.index=0;},
 8|10=>{if c.frame==c.frames{c.phase=if c.phase==8{9}else{11};c.index=0;c.frame=0;c.search=0;}else if c.search==0{c.low=0;c.high=c.layers;c.search=1;}else if c.search==1{if c.low==c.high{c.scan=c.low;c.search=2;}else{let mid=c.low+(c.high-c.low)/2;if let Some(order)={let target=s.frame_layer_id(c.frame);Self::compare(&mut c,s.layer_id(o.sorted[mid]),target)}{if order==Ordering::Less{c.low=mid+1}else{c.high=mid}}}}else if c.scan==c.layers{c.frame+=1;c.search=0;}else{let layer=o.sorted[c.scan];if let Some(order)={let target=s.frame_layer_id(c.frame);Self::compare(&mut c,s.layer_id(layer),target)}{if order!=Ordering::Equal{c.frame+=1;c.search=0;}else if c.phase==8{o.counts[layer]=o.counts[layer].checked_add(1).ok_or_else(||Self::fault("page cache membership extent overflow"))?;c.scan+=1;}else{c.search=3;}}}},
 9=>{if c.index<c.layers{let out=&mut o.objects[c.index];out.try_reserve_exact(o.counts[c.index]).map_err(|_|Self::fault("page cache member headers reservation failed"))?;p.retained_capacity_bytes=out.capacity()*size_of::<String>();c.index+=1;}else{c.phase=10;c.search=0;}},11=>{},_=>return Err(Self::fault("page cache phase invalid"))}}self.control=c;if p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(Self::fault("page cache allocator exceeded original capacity grant").with_retained_progress(p))}Ok(if c.phase==11{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn is_ready(&self)->bool{!self.closing&&self.control.phase==11}
 pub fn install_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.control.phase<11||self.control.phase>12{return Err(Self::fault("page cache install lacks admission"))}Ok(RetirementDemand{copy_bytes:2*size_of::<Control>()+3*size_of::<Vec<String>>(),depth:1,..Default::default()})}
 pub fn install(&mut self,page:&mut Page,g:RetainedCloneGrant,_capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{self.install_owned(page,g)}
 /// 🌱️ Installs only cache headers into an unpublished parent payload retained by its original mutation preparation.
 pub fn install_prepared_parent(&mut self,parent:&mut ParentPage,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.install_fields(&mut parent.layer_ids,&mut parent.layers,g)}
 fn install_owned(&mut self,page:&mut Page,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.install_fields(&mut page.layer_ids,&mut page.layers,g)}
 fn install_fields(&mut self,layer_ids:&mut Vec<String>,layers:&mut[Layer],g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.install_demand()?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut c=self.control;if layers.len()!=c.layers{return Err(Self::fault("page cache install source extent changed"))}if c.phase==12{return Ok(RetainedCloneStep::Complete(Default::default()))}let o=self.owners.as_mut().expect("prepared original cache owners");if c.install==0{std::mem::swap(layer_ids,&mut o.layer_ids)}else{std::mem::swap(&mut layers[c.install-1].object_ids,&mut o.objects[c.install-1])}c.install+=1;if c.install==c.layers+1{c.phase=12}self.control=c;let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};Ok(if c.phase==12{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(Self::fault("page cache close not begun"))}self.retirement.next_owner_demands::<Owners>(self.owners.is_some(),&None,body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(step)=self.retirement.begin_granted(&mut self.owners,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.owners.is_none()&&self.retirement.is_empty()}
}
impl Drop for PageCachePreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original page cache owners need funded close")}}
#[cfg(test)]
#[path="🧪️tests/🦀️.rs"]
mod tests;

impl PageCachePreparation{
 pub fn prepared_layer_ids(&self)->Result<&[String],ValueError>{if !self.is_ready(){return Err(Self::fault("page cache read lacks completed preparation"))}Ok(&self.owners().layer_ids)}
 pub fn prepared_objects(&self,layer:usize)->Result<&[String],ValueError>{if !self.is_ready(){return Err(Self::fault("page cache read lacks completed preparation"))}self.owners().objects.get(layer).map(Vec::as_slice).ok_or_else(||Self::fault("page cache read layer is invalid"))}
}
